{
  "book_code": "TADAM",
  "verses": [
    {
      "chapter": 28,
      "verse": 3,
      "text_ar": "بعد أن سجدت للرب، أخذ ميخائيل رئيس ملائكة الله بيدي فوراً و"
    },
    {
      "chapter": 28,
      "verse": 4,
      "text_ar": "طردني خارج فردوس «الرؤيا» وأمر الله. وكان ميخائيل يمسك بقضيب في يده، فلمس المياه التي حول الفردوس فتجمّدت بقوة."
    },
    {
      "chapter": 29,
      "verse": 1,
      "text_ar": "وعبرتُ، وعبر معي ميخائيل رئيس الملائكة، وأعادني إلى"
    },
    {
      "chapter": 29,
      "verse": 2,
      "text_ar": "المكان الذي اختطفني منه. اسمع، يا بني شيث، حتى بقية الأسرار [والأسرار المقدسة] التي ستكون، والتي كُشفت لي عندما أكلت من شجرة"
    },
    {
      "chapter": 29,
      "verse": 3,
      "text_ar": "المعرفة، وعرفتُ وأدركتُ ما سيحدث في هذا الدهر؛ [وما ينوي الله فعله]"
    }
  ]
}
